CREATE TABLE prj24_stock (product_id INTEGER PRIMARY KEY, product_name TEXT NOT NULL, quantity INTEGER NOT NULL CHECK (quantity >= 0));
CREATE TABLE prj24_shipments (shipment_id INTEGER PRIMARY KEY, product_id INTEGER NOT NULL, quantity INTEGER NOT NULL, shipment_state TEXT NOT NULL);
INSERT INTO prj24_stock VALUES (1, 'Keyboard', 10);
BEGIN;
INSERT INTO prj24_shipments VALUES (501, 1, 3, 'created');
UPDATE prj24_stock SET quantity = quantity - 3 WHERE product_id = 1 AND quantity >= 3;
COMMIT;
SELECT quantity FROM prj24_stock WHERE product_id = 1;

